using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "IndigoSoulEffect", menuName = "Data/Battle/Effects/Cellarius/IndigoSoulEffect")]
public class IndigoSoulEffect : Effect
{
	[SerializeField]
	private RefreshAction refreshAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedDescription = GetLocalizedDescription();
		if (amount == EffectsValues.NO_VALUE || amount == -1)
		{
			return GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, refreshAction.GetActionDescription(EffectsValues.NO_VALUE).RemoveLast(), GetNumberToReplaceWithX());
		}
		return Smart.Format(localizedDescription, refreshAction.GetActionDescription(EffectsValues.NO_VALUE).RemoveLast(), amount);
	}
}
